import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // The change replaces `value[0] === "-" || value[0] === "+"` with `value[0] === "-" || value[0] === ""`
    // This causes an incorrect JSON integer parsing for empty string after '+'
    // Example: "+" should be invalid, but the new code treats it as valid
    const input = '+';
    assert.throws(() => load(input), /cannot resolve a node with !<tag:yaml.org,2002:int> explicit tag/);

    // But the expected behavior is that auto-converted "" (empty string) should not be interpreted as "0"
    // The original code would reject "+" because it has no digits after the sign
    // The modified code incorrectly handles "+" as if it's "0" due to empty string handling

    // Test that a plain integer like "-" or "+" should be rejected
    assert.throws(() => load("-"), /cannot resolve a node with !<tag:yaml.org,2002:int> explicit tag/);
    assert.throws(() => load("+"), /cannot resolve a node with !<tag:yaml.org,2002:int> explicit tag/);

    // Now test that actual valid integers work correctly
    assert.strictEqual(load("0"), 0);
    assert.strictEqual(load("-42"), -42);
    assert.strictEqual(load("+42"), 42);
  });
});

