describe('proof', () => {
  it('fails on the patched build', () => {
    // The original pattern allowed up to 2 padding equals signs
    // The patched pattern only allows exactly one padding equals sign
    // This means strings with two padding equals signs are now rejected
    // even though they are valid base64
    const validBase64WithTwoPadding = 'aGVsbG8='; // This is valid with 2 padding chars
    const validBase64WithOnePadding = 'aGVsbG8='; // This is valid with 1 padding char

    // Both should be valid, but the patch makes the first one invalid
    assert.strictEqual(load('!!binary ' + validBase64WithTwoPadding), 'hello');
    assert.strictEqual(load('!!binary ' + validBase64WithOnePadding), 'hello');
  });
});

