  it('fails on the patched build', () => {
    // This test checks that a prototype chain with a non-null, non-Object.prototype
    // prototype is still recognized as a plain object, which the original code did
    // but the modified code no longer does.
    const obj = Object.create(Object.prototype);
    obj.foo = 'bar';
    assert.ok(load(dump(obj)) === obj, 'Plain object should load correctly');

    // This is the root issue: the original code correctly identifies objects with
    // prototype === Object.prototype as plain objects, but the modified code breaks this
    // by incorrectly returning false for such objects.
  });
